-- 674_farmer_cull_spec_wash_three_prose_aspects.sql
--
-- Owner cull ruling, decision 4 of 2026-08-31 ("delete the seven farmer tools", loanzy lane's
-- six-decisions handoff): the seven unresearched farmerinsurance.uk tools are deleted at the
-- artefact (21/21 retired urls 404). This migration completes the SPEC layer half handed to the
-- copy_quality_two_stage lane: the briefing / strategy / vertical_landscape aspects still
-- PRESCRIBE those tools in prose, and specs feed planning/generation — a future generation pass
-- reading them re-mints dead-tool copy (rerenders are unaffected; they read content_data).
-- The tools aspect was superseded by the loanzy lane (successor 8031bb1c); offer_ordering
-- re-derives via the analyser. This file does the remaining three, supersede-never-edit:
-- successor row inserted, predecessor kept with superseded_at.
--
-- Census 2026-08-31 (this lane, exact ids): predecessors 38666a42-e9b5-4a81-aa2f-ab6aa2da9c44 (briefing),
-- 43b01298-b25c-4e6c-abfb-0506bd0e3d78 (strategy), a7ce9ee2-c485-4f6f-89c9-cab311e13fdb (vertical_landscape). Loanzy's
-- same-day handover counted ~19 prose mentions; this lane's broader-pattern census found more
-- lines (incl. a defensible_moat mention only the class battery caught) — the battery below is
-- the binding test, not either count.
--
-- Surgery is deletion-first (built + needle-asserted offline, farmer_spec_surgery.py in the
-- lane scratchpad; every edit asserted its exact needle occurred once): the seven offering
-- entries and the tool page-type recommendation removed whole; prescription sentences end
-- where the tool clause began; exemplar ANALYSIS of other sites' calculators (MSE/ABI/NFU) is
-- deliberately KEPT — analysis of others is research grounding, not a prescription of ours.
--
-- Guards: (1) predecessors are flipped BY CENSUSED ID with is_current in the predicate — a
-- producer regeneration flips the id, so drift refuses loudly (668's lesson, adapted: identity
-- beats exact-text here because the whole row is being superseded). (2) The partial unique
-- index idx_site_specs_current (site_id,aspect) WHERE is_current makes a mid-transaction
-- producer mint COLLIDE at commit — one transaction errors, nothing silently lost (the 667
-- false-green shape cannot occur: we insert the current row rather than updating in place).
-- (3) The verify block runs the FULL seven-name class battery on all three successors (never
-- the sharpest finding alone — the 646/647 lesson) AND its positive control on the kept
-- predecessors. (4) schema_migrations INSERT rides INSIDE the transaction (668's
-- recorded-but-unapplied lesson). Apply with:
--   psql -v mig_checksum=<md5 of this file> -f <this file>
-- ROLLBACK: 674_..._ROLLBACK.sql (refuses if the analyser has since superseded our successors).

BEGIN;

INSERT INTO migration_backups (migration_name, target_table, target_id, old_value, notes)
SELECT '674_farmer_cull_spec_wash_three_prose_aspects', 'site_specs', ss.id::text,
       jsonb_build_object('data', ss.data, 'is_current', ss.is_current, 'superseded_at', ss.superseded_at),
       'pre-674 ' || ss.aspect || ' for farmerinsurance.uk'
FROM site_specs ss
WHERE ss.id IN ('38666a42-e9b5-4a81-aa2f-ab6aa2da9c44','43b01298-b25c-4e6c-abfb-0506bd0e3d78','a7ce9ee2-c485-4f6f-89c9-cab311e13fdb');

DO $mig$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM migration_backups
   WHERE migration_name='674_farmer_cull_spec_wash_three_prose_aspects';
  IF n <> 3 THEN RAISE EXCEPTION '674: % backup rows, want 3 — a censused predecessor is missing; re-census before applying', n; END IF;

  UPDATE site_specs SET is_current=false, superseded_at=now() WHERE id='38666a42-e9b5-4a81-aa2f-ab6aa2da9c44' AND is_current;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION '674: briefing predecessor 38666a42-e9b5-4a81-aa2f-ab6aa2da9c44 is no longer current — regenerated since the 2026-08-31 census; re-census and re-base, do not apply blind'; END IF;

  UPDATE site_specs SET is_current=false, superseded_at=now() WHERE id='43b01298-b25c-4e6c-abfb-0506bd0e3d78' AND is_current;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION '674: strategy predecessor 43b01298-b25c-4e6c-abfb-0506bd0e3d78 is no longer current — regenerated since the 2026-08-31 census; re-census and re-base, do not apply blind'; END IF;

  UPDATE site_specs SET is_current=false, superseded_at=now() WHERE id='a7ce9ee2-c485-4f6f-89c9-cab311e13fdb' AND is_current;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION '674: vertical_landscape predecessor a7ce9ee2-c485-4f6f-89c9-cab311e13fdb is no longer current — regenerated since the 2026-08-31 census; re-census and re-base, do not apply blind'; END IF;
END $mig$;

INSERT INTO site_specs (site_id, aspect, data, source, source_agent, notes, is_current, created_by)
VALUES ('99cae989-2413-430d-b026-59dfeeb638c0', 'briefing', $j674b${"gaps": ["contact_email", "contact_phone", "location", "people", "examples"], "jobs": {"offerings": [{"name": "Farm Insurance Explainers", "description": "Plain-English guides to the types of insurance cover UK farmers need — buildings, contents, livestock, machinery, crop, and liability. Each guide covers typical cover, common exclusions, what to watch for in a policy document, and what questions to ask a broker. Written at the depth of a specialist reference, not a product brochure."}, {"name": "Coverage Comparison Information", "description": "Side-by-side information tables comparing what different policy types typically cover, helping farmers understand what to look for — not routing to applications or ranking named providers."}, {"name": "Regulatory Rights and Claims Guidance", "description": "Information on farmer rights when making claims, FOS complaint routes, and what insurers are obliged to provide under UK law — with accurate references and links to official FCA and FOS sources."}, {"name": "Seasonal Risk Guides", "description": "Content covering seasonal risks — harvest fire in August/September, lambing losses in February/March, flooding in winter — and which insurance products are relevant at each point in the UK farming calendar."}, {"name": "Glossary and Jargon Buster", "description": "Definitions of insurance terms — indemnity, excess, reinstatement, sum insured, index-linking, average clause, livestock mortality, all-risks, public liability, employers liability — explained in farming-context language with worked examples."}], "site_jobs": [{"job": "Understand what farm insurance typically covers", "detail": "Visitors must be able to read clear, deep guides on each major insurance type — buildings, livestock, machinery, crops, public liability, employers liability, business interruption — and leave knowing what is typically included, what is commonly excluded, and what questions to ask a regulated broker."}, {"job": "Check whether their current cover is adequate", "detail": "Guides help visitors self-audit their sums insured and coverage gaps without submitting personal data or being routed to an application."}, {"job": "Understand their rights when a claim goes wrong", "detail": "Visitors who have had a claim disputed, refused, or mishandled must be able to find plain-English guidance on their rights under UK law, how to escalate to the Financial Ombudsman Service, and what the insurer is legally required to do — with links to official FCA and FOS sources."}, {"job": "Decode insurance terminology in a farming context", "detail": "Visitors encountering unfamiliar terms — indemnity, reinstatement, excess, index-linking, average clause, livestock mortality, all-risks — must be able to find accurate, farming-specific definitions with worked examples in a static glossary."}, {"job": "Find insurance information relevant to their current point in the farming year", "detail": "Seasonal risk content — harvest fire risk in August, lambing loss risk in February, flood risk in winter — must be surfaced at the right moment so a farmer can find everything relevant to their current situation in one place, without having to navigate by product category."}, {"job": "Understand what type of insurance they actually need", "detail": "A plain-English starter guide helps visitors who do not know where to start — by farm type, tenure, employee status, public access, and diversification activities — to arrive at a prioritised list of policy types to consider, with links to relevant explainer guides."}, {"job": "Find a route to regulated help without being introduced to a specific insurer", "detail": "Visitors who are ready to speak to a professional must be directed clearly to the FCA register and given guidance on what to look for in a regulated agricultural insurance broker — without the site constituting an introduction or referral."}]}, "site": {"tagline": null, "company_name": "Farmer Insurance UK", "site_purpose": "An independent information and guidance resource covering insurance topics relevant to UK farmers and rural businesses. The site explains what farm insurance policies typically cover — buildings, livestock, machinery, crops, and liability — in plain farming language, without acting as an insurer, broker, or introducer. It helps farmers understand what insurance they need, what to look for in a policy document, and what rights they have when a claim goes wrong. It does not sell, arrange, or recommend any insurance product, and has no ties to any insurer or broker panel."}, "tone": "authoritative", "voice": {"avoid": "Any language implying the site can arrange, recommend, or introduce readers to a specific insurer or broker — this is a regulated activity the site cannot perform. Generic reassurances with no substance: 'we help farmers find the best cover', 'trusted by thousands of farmers'. American insurance terminology: 'deductible' (use 'excess'), 'coverage' (use 'cover'). Urgency or scarcity tactics: 'act now', 'don't wait until it's too late', 'limited time'. Vague statistics without a cited primary source. Oversimplification that could mislead: 'farm insurance covers everything on your farm'. Any suggestion of affiliation with or endorsement by NFU Mutual, the ABI, Farmers Insurance Group (US), or any named insurer. Content that reads like a comparison site — ranking insurers, showing prices side by side. The verbs 'buy', 'apply', 'get covered today', 'claim your quote'. Passive constructions that obscure who does what. Thin content that covers a topic at headline level only.", "voice": "The writing sounds like a knowledgeable neighbour who farms themselves and has also read every policy document so the reader does not have to. Practical, grounded, and no-nonsense — professional but not stiff, with contractions used naturally. Authority comes from depth and specificity: real UK policy term names, actual FCA rule references, named FOS processes, and genuine farming scenarios — not from claims about the site itself. The tone is calm and reassuring without being dismissive of serious financial risk. It treats readers as capable adults who know farming well but may not know insurance terminology. Second person throughout (you, your, your farm). Scenario-first structure: introduce the farming risk before naming the insurance concept. Headings answer real questions farmers would ask. Sentences are medium length — short declarative statements for key points, slightly longer for explanations — with a varied rhythm that feels like a well-written farming magazine article rather than a compliance document or a fintech landing page."}, "extras": {"people": [], "examples": [], "has_blog": true, "extra_sections": ["Seasonal Risk Guides", "Glossary and Jargon Buster", "Insurance Tools", "Claims and Dispute Guidance", "About This Site", "Legal and Compliance Notice", "How to Find a Regulated Agricultural Insurance Broker", "UK Health and Agricultural Insurer Directory"]}, "contact": {"location": "United Kingdom", "contact_email": "[INFERRED] hello@farmerinsurance.uk", "contact_phone": null}, "tagline": null, "audience": {"audience": "UK farmers — both tenant and owner-occupier — who need to understand what insurance they should hold, what their policies actually cover, and what to do when a claim is disputed or refused. Picture a mixed-farm operator in their forties who knows every inch of their land and every cost of running it, but who finds insurance policy documents confusing and distrusts sites that are obviously trying to sell them something. They are time-poor, practically minded, and deeply sceptical of vague reassurances. They want specific, honest information they can act on — not a sales funnel. Secondary readers include smallholders, rural business owners, farm workers, agricultural students, farm advisers, and land agents who need to understand the insurance landscape around farm businesses."}, "industry": "Insurance Information & Education", "site_type": "content", "company_name": "Farmer Insurance UK", "briefing_confidence": 0.82, "recommended_builder": "pageflow-builder"}$j674b$::jsonb, 'owner_review', 'copy_quality_two_stage',
        'Supersedes 38666a42-e9b5-4a81-aa2f-ab6aa2da9c44 per the owner cull ruling (decision 4, 2026-08-31): the seven deleted tools removed from prescription prose; exemplar analysis kept; predecessor retained (superseded, not deleted). Surgery + class battery: copy_quality_two_stage lane, 674.',
        true, 'copy_quality_two_stage');

INSERT INTO site_specs (site_id, aspect, data, source, source_agent, notes, is_current, created_by)
VALUES ('99cae989-2413-430d-b026-59dfeeb638c0', 'strategy', $j674s${"tone": "authoritative", "site_type": "content-hub", "money_flow": "Display advertising revenue arrives from rural and agricultural sector advertisers — machinery manufacturers, farm software companies, agricultural suppliers — paying CPM or CPC rates against the site's UK farming audience; revenue accrues continuously as traffic grows and is paid monthly by the ad network. Secondary affiliate revenue arrives when a visitor clicks through to a non-regulated farm product (safety equipment, management software) and completes a purchase, with commission paid by the affiliate program on a per-conversion basis.", "domain_type": "generic_industry", "growth_path": "Phase one: establish the core guide library across the six primary coverage categories (buildings, livestock, machinery, crops, public liability, employers liability) plus a foundational claims rights section and the glossary. Phase two: build out seasonal content hubs that group all relevant guides for each major farming period, enabling farming-calendar-based navigation. Phase three: grow the claims and dispute content into the site's most distinctive section — the area no incumbent serves well. Phase four: introduce a verified directory of FCA-regulated agricultural insurance brokers (linked to FCA register entries) and a news feed covering insurance regulation and market developments relevant to UK farmers, extending the site's authority and return-visit reasons. Display advertising scales with traffic volume; affiliate revenue from non-regulated farm products (safety equipment, management software) grows as the audience deepens.", "search_intent": {"primary_intent": "informational", "likely_searches": ["farm insurance UK", "what does farm insurance cover", "agricultural insurance UK", "livestock insurance UK", "farm buildings insurance", "farm machinery insurance", "crop insurance UK", "public liability farm", "employers liability farm UK", "farm insurance claim refused", "farm insurance glossary", "reinstatement value farm building", "livestock mortality insurance", "business interruption farm", "harvest insurance UK", "lambing insurance"], "high_value_terms": ["farm insurance UK", "agricultural insurance UK", "livestock insurance UK", "farm buildings insurance UK", "farm machinery insurance UK", "farm insurance claim rights UK"]}, "revenue_models": {"affiliate": {"fit": "possible", "reasoning": "Affiliate links to non-regulated products — farm safety equipment, farm management software, agricultural PPE — are viable. Affiliate links to insurance products would constitute insurance distribution and are excluded. Revenue potential is modest but clean and compliance-safe."}, "saas_tools": {"fit": "possible", "reasoning": "Illustrative calculators are genuinely useful to the audience and can be monetised through premium downloadable outputs or soft sponsorship labelling without crossing into regulated activity. Secondary model at best; tools exist primarily to drive engagement and return visits rather than direct revenue."}, "primary_model": "display_advertising", "direct_business": {"fit": "poor_fit", "reasoning": "The domain is an unbuilt blank slate with no existing business behind it. Building a regulated insurance business from scratch would require FCA authorisation — a multi-year and capital-intensive process incompatible with a domain development strategy."}, "lead_generation": {"fit": "poor_fit", "reasoning": "Passing enquiries to insurers or brokers is insurance distribution under FSMA 2000 and requires FCA authorisation. This domain cannot legally operate as a lead-generation site without regulatory status it does not hold."}, "secondary_models": ["affiliate", "saas_tools"], "sponsored_listings": {"fit": "poor_fit", "reasoning": "Sponsored placement of insurers or brokers within a directory or guide risks constituting insurance distribution or creating a regulated financial promotion without FCA authorisation. The compliance risk makes this model unavailable in its typical form."}, "display_advertising": {"fit": "strong_fit", "reasoning": "A high-traffic UK agricultural insurance information hub attracts premium display advertising from rural and farming sector advertisers — machinery manufacturers, agricultural suppliers, rural finance providers, land agents, farm software companies. CPMs in specialist agricultural and financial-adjacent audiences are materially above generic content verticals. This is the primary monetisation path for an unregulated information site in this space."}}, "recurring_value": "The seasonal risk content changes meaningfully through the UK farming calendar — harvest fire guides become relevant in August, lambing risk guides in February, flood risk content in winter — giving farmers a reason to return at each major seasonal transition; the claims and dispute section draws return visits at the highest-urgency moments in a farmer's policy lifecycle.", "trust_threshold": "Trust must be established before a visitor acts on any guidance, because the subject matter involves significant financial decisions and the risk of misunderstanding a policy exclusion could cost tens of thousands of pounds; the site earns this trust through specificity (named FCA rules, real FOS timeframes, exact policy term definitions) and structural transparency (explicit statements that the site is not FCA-authorised and cannot give financial advice), which together signal editorial integrity rather than commercial motivation.", "content_strategy": "Content is organised around two axes: farming situation (buildings, livestock, machinery, crops, liability, claims disputes) and farming season (lambing, harvest, flooding, winter). The primary draw is deep single-topic guides that serve as the most complete reference a UK farmer can find on each subject — covering typical cover, common exclusions, what to watch for in a policy document, and what questions to ask a broker. The secondary draw is the claims crisis moment: what to do when a claim is disputed, refused, or mishandled, with FOS rights explained accurately and linked to official sources. A structured farming-context glossary functions as both a reference tool and an SEO asset. Seasonal content — harvest fire risk in August, lambing loss risk in February, flood risk in winter — provides timely relevance that draws return visits at the moments farmers most need the information. All content follows the scenario-first pattern: introduce the farming risk before naming the insurance concept. Trust is built through specificity — named FCA rule references, actual policy term names, real FOS complaint timeframes — not through claims about the site itself.", "value_proposition": "The only independent, editorially unaffiliated UK resource that explains agricultural insurance in plain farming language — covering what policies typically include, what to watch for in a policy document, and what rights you have when a claim goes wrong.", "site_type_reasoning": "The domain is a generic industry term on a blank-slate build with no regulated business behind it and no legal route to transaction-based revenue from insurance products. The highest-value unregulated position is an editorial content hub: deep informational guides, a glossary, and seasonal risk content organised around the UK farming calendar. This is consistent with the research classification (hub, confidence 0.72), the compliance constraints (FSMA 2000, FCA authorisation requirements), and the competitive gap analysis (no incumbent serves the agricultural insurance information space with editorial independence and farming-specific depth). An authority-portal classification was considered — the domain has the right shape for one — but the FCA constraint eliminates the directory-of-regulated-entities model that typically powers authority portals. Content hub is the correct type: articles and guides are the primary product and display advertising monetises the traffic.", "competitive_position": {"defensible_moat": "The moat is structural independence combined with agricultural specificity and depth. NFU Mutual cannot be editorially independent — it sells policies. The ABI cannot be farming-specific — it serves the whole insurance industry. General consumer sites (MSE, Which?) cannot go deep enough on agricultural insurance to be the authoritative reference. A site that is genuinely unaffiliated with any insurer or broker, written at the depth of a specialist farming trade publication, organised around how farmers actually experience risk across the year — this combination is not replicable by any incumbent without abandoning their commercial model.", "gap_opportunity": "The clearest gap — identified directly in the vertical landscape research — is the claims crisis moment: when a farmer has already made a claim and it has been disputed, refused, or mishandled. Neither insurer sites (which have a structural conflict of interest), nor general consumer sites (which lack agricultural specificity), nor the ABI (which writes for industry as much as consumer) serve a farmer in this position with depth. A 'what to do when your claim is refused' guide and a 'questions to ask your loss adjuster' resource represent territory no incumbent owns adequately. Combined with scenario-led pre-purchase guides, seasonal risk content organised around the UK farming calendar, farmerinsurance.uk can own both the research moment and the crisis moment — the two highest-intent visits an insurance information site can capture.", "current_landscape": "The UK farm insurance search space is dominated by three types of incumbent: regulated insurers (NFU Mutual, Cornish Mutual) who publish product-focused content with commercial intent behind every page; trade bodies (ABI) who publish authoritative but industry-facing or broadly generic consumer guidance; and general comparison or broker sites who require FCA authorisation to operate and focus on quote generation rather than information depth. NFU Mutual's editorial section is the closest to a genuine farming content resource, but it exists to sell NFU Mutual products and cannot be editorially independent. No incumbent fills the gap of a deep, independent, unregulated information resource written specifically for UK farmers navigating policy decisions, coverage gaps, and claim disputes."}, "domain_type_reasoning": "farmerinsurance.uk combines a clear audience descriptor ('farmer') with a service category ('insurance') under the UK country-code TLD. It names no specific business, person, or brand. Like 'londonplumbers.co.uk' or 'gaswholesalers.com', it signals an entire subject-matter space rather than a single operator. Treating it as a single business would waste its generic authority — the domain's real value is as the canonical UK resource for agricultural insurance information. The .uk TLD anchors it firmly to the UK market, reinforcing the generic-industry classification.", "recommended_page_types": [{"page_type": "index", "reasoning": "The home page is the entry point for branded and generic searches. It should orient the visitor immediately — independent UK farm insurance information resource, no insurer ties, content organised by farming situation — and surface the highest-value guides and seasonal content without burying them behind navigation."}, {"page_type": "blog-index", "reasoning": "An editorial index page organising guides by topic category (buildings, livestock, machinery, liability, crops, claims) is essential for navigation and SEO architecture. The research identifies eight topic categories; a blog-index style listing page allows visitors to browse by their situation rather than by insurance product type, matching how farmers actually think about their risks."}, {"page_type": "blog-post", "reasoning": "Deep individual guide pages are the primary content unit — each one covering a specific topic (farm buildings insurance, livestock mortality cover, employers liability, harvest fire risk, what to do when a claim is refused) at the depth of a specialist reference. These pages carry the bulk of organic search value and must each be the most useful single resource a UK farmer can find on that topic."}, {"page_type": "entity-directory", "reasoning": "A verified directory of UK health insurers and agricultural insurance providers — clearly labelled as external links to regulated firms, not endorsements — provides a useful reference resource and supports the site's editorial independence positioning. The research specifically recommends a health-insurer directory as a separate page; an agricultural insurance provider directory (linking to the FCA register entries for verification) extends this usefully without constituting introduction or distribution."}, {"page_type": "entity-page", "reasoning": "Individual glossary term pages — each defining a single insurance term (indemnity, reinstatement, excess, index-linking, average clause, livestock mortality, all-risks) in farming-context language with a worked example — serve both SEO and the site's core jargon-buster function. The vertical landscape research names glossary depth as a key success factor across all three exemplars analysed."}, {"page_type": "content", "reasoning": "Standard content pages are needed for the site's compliance and transparency infrastructure: an explicit 'About this site' page stating the site is not FCA-authorised and cannot give financial advice; a compliance and legal notice page; a contact page; and a 'How to find a regulated agricultural insurance broker' guide (linking to the FCA register as the verification tool rather than building a commercial broker finder)."}], "satisfaction_condition": "A visitor leaves having understood what a specific type of farm insurance typically covers, what exclusions to look for in their policy document, or what steps to take if their claim has been disputed — with enough concrete information to have a meaningful conversation with a regulated broker or the FOS."}$j674s$::jsonb, 'owner_review', 'copy_quality_two_stage',
        'Supersedes 43b01298-b25c-4e6c-abfb-0506bd0e3d78 per the owner cull ruling (decision 4, 2026-08-31): the seven deleted tools removed from prescription prose; exemplar analysis kept; predecessor retained (superseded, not deleted). Surgery + class battery: copy_quality_two_stage lane, 674.',
        true, 'copy_quality_two_stage');

INSERT INTO site_specs (site_id, aspect, data, source, source_agent, notes, is_current, created_by)
VALUES ('99cae989-2413-430d-b026-59dfeeb638c0', 'vertical_landscape', $j674v${"lessons": {"adapt": ["NFU Mutual's seasonal content hub structure adapted without the commercial product links — group guides by farming season and enterprise type (arable, livestock, mixed) so a farmer can navigate by how they think about their year, not by insurance product category", "ABI's data and statistics authority adapted by citing ABI and NFU primary data throughout guides — the site cannot produce primary data itself, but it can be the most thorough curator and explainer of existing authoritative data sources, becoming the place that links everything together", "NFU's community-aligned positioning adapted as editorial independence rather than mutual ownership — the trust signal is 'no ties to any insurer or broker' rather than 'we are owned by farmers', but both achieve the same goal of structural alignment with the reader's interests", "NFU's local agent finder concept adapted as a 'how to find a regulated agricultural insurance broker' guide — cannot build a commercial broker finder without FCA authorisation, but can explain what to look for in an agricultural broker and link to the FCA register as the verification tool"], "adopt": ["Scenario-first content structure: introduce the farming risk (a machinery fire, a flooded field, a livestock disease outbreak) before naming the insurance concept — this is the MSE pattern and it works because it makes abstract information feel immediately relevant to the reader's real situation", "Named regulatory body citations with links to official sources in every guide where reader rights are discussed — FCA, FOS, ABI — never paraphrase a legal right in a way that could mislead, always link to the authoritative source", "Seasonal content organisation that mirrors the UK farming calendar — lambing in February/March, harvest fire risk in August/September, flood risk in winter — so a farmer arriving at a particular moment in their year finds content that speaks directly to their current situation", "Explicit 'what this site can and cannot do' statement on every guide page — the MSE pattern of naming its own limitations before the reader discovers them is a powerful trust builder, not a weakness", "Deep single-topic guides rather than shallow multi-topic overviews — each guide should be the most useful single resource a UK farmer can find on that topic, which is how MSE earns its dominant search and return-visit position", "Date of last review visible on every guide — signals active editorial maintenance and prevents stale content from eroding trust", "Structured glossary with farming-context examples for every insurance term — the ABI's canonical definition depth, applied to agricultural insurance vocabulary specifically", "Information-framed CTAs that direct to more useful content rather than to a transaction — 'read our guide to livestock exclusions' as the default next step, not 'get a quote'"], "avoid": ["Any content pattern that implies the site can recommend, rank, or introduce readers to specific insurers — NFU Mutual can do this because it is FCA-authorised; farmerinsurance.uk cannot and must not imply otherwise", "Generic reassurance language without substance — 'we help farmers find the best cover' is the kind of line that appears on broker and comparison sites and would signal to readers that this site is commercially motivated rather than editorially independent", "Urgency or scarcity design patterns — none of the three exemplars use them on information pages and their absence is itself a trust signal; adding them would immediately signal commercial pressure incompatible with an independent information resource", "American insurance terminology or imagery — 'deductible', 'coverage', dollar signs, or US farm imagery would undermine the UK-specific authority that is the site's core value proposition", "Shallow content that covers a topic at headline level — MSE and ABI both succeed because their depth is genuinely greater than competitors; matching their depth is the baseline, not an aspiration", "Vague statistics without a cited primary source — 'most farmers are underinsured' without an ABI or NFU study citation would read as marketing copy rather than editorial fact", "Presenting the site as affiliated with or endorsed by NFU Mutual, the ABI, or any other named body — the independence positioning requires explicit distance from all commercial and institutional relationships"]}, "patterns": {"tools": "Tools across the three exemplars share a common logic: they help the reader understand their situation without committing them to a commercial transaction. MSE's eligibility calculators, ABI's glossary search, and NFU's agent finder all serve the reader's decision process rather than the site's conversion rate. Outputs are always accompanied by caveats and signposts to next steps (speak to a broker, contact the FOS, find a local agent) — no tool presents its output as a definitive answer. Complexity is calibrated to the decision: simple glossary lookups are instant, more complex calculations ask only for the minimum inputs needed to produce a useful output. All tools are framed as decision-support rather than application pipelines.", "design": "All three prioritise information density and legibility over visual decoration — the design serves the content, not the other way around. Navigation structures reflect reader goals rather than internal product hierarchies. Images are used contextually and authentically — real weather events, real farm scenes, real products — rather than stock photography that signals genericness. White space is used deliberately to aid scanning of dense information, not as a luxury design statement. All three avoid dark or heavy colour schemes in consumer-facing sections — information content in this sector reads best in light, clean environments. None of the three uses urgency design patterns (countdown timers, scarcity indicators, flashing CTAs) on information pages.", "content": "All three exemplars organise content around reader situations and real-world events rather than product taxonomies — MSE by financial scenario, ABI by risk event type (flooding, cold weather), NFU by farming activity and season. All three publish at significant depth — thin content is absent in each case. All three maintain a clear separation between information and transaction: the information pages never blur into sales pages. Seasonal and timely content is used by all three to maintain relevance and return visits — content is not treated as permanent static inventory but as a living resource that responds to what is happening to readers right now. All three cite specific named bodies (FCA, FOS, ABI itself, NFU) and specific figures — not vague reassurances — as their primary trust mechanism."}, "confidence": 0.84, "exemplars_analyzed": [{"url": "https://www.moneysavingexpert.com", "positioning": "The UK's dominant independent consumer finance information resource — explicitly not a seller, explicitly on the reader's side. Earns authority by being demonstrably more useful than any commercial site in the same space, with regulatory references and named bodies (FCA, FOS) that signal genuine expertise rather than marketing copy.", "notable_tools": ["Eligibility calculators that use soft-credit-check logic to give personalised outputs without committing the reader to an application — separates information from transaction", "Comparison tables that present factual differences between product types rather than ranking named providers by commission value", "Step-by-step complaint letter generators that give the reader agency and reduce the perceived barrier to exercising their rights", "Forum-integrated content where expert-moderated community answers supplement editorial guides — extends depth without inflating the editorial workload"], "trust_signals": ["Named regulatory bodies cited in context — FCA, FOS, PRA — with links to official sources rather than internal paraphrases", "Clear statement of what the site earns revenue from and how that affects (or does not affect) editorial recommendations", "Date of last review visible on every guide — signals active maintenance, not static content", "Named editorial team with credentials — 'Martin Lewis' as a real person readers can hold accountable rather than a faceless brand", "Explicit 'what we can't do' statements prevent readers from over-relying on information that requires professional advice", "No urgency language anywhere — the absence of 'act now' and 'limited offer' is itself a trust signal in a space saturated with pressure tactics"], "success_factors": ["Radical transparency about what the site can and cannot do for the reader — this disarms scepticism before it forms and converts visitors into repeat users", "Every guide is structured around what happens to the reader in a real scenario before any product or concept is introduced — scenario-first writing makes abstract information feel personally relevant", "Named regulatory bodies and actual rule references (not paraphrases) throughout guides — specificity is the primary trust mechanism, not brand claims", "Content is organised by reader situation and need, not by product category — 'I need to complain about my insurer' is a navigation concept, not 'Complaints' as a menu label", "Calculators and eligibility checkers are framed as decision-support tools, not lead-generation funnels — outputs are estimates with clear caveats, preserving editorial integrity", "Plain English throughout with no jargon assumed — but never condescending, which maintains respect for the reader's intelligence", "High content density without visual clutter — information is the product, and the layout serves information rather than aesthetics or advertising", "Frequent updates and date-stamped content signal reliability and editorial rigour — a guide from three years ago on a regulated topic is a liability; freshness signals care"]}, {"url": "https://www.abi.org.uk", "positioning": "The authoritative industry-body voice for UK insurance — positioned as the definitive factual source rather than a consumer advocate or a seller. Succeeds because its institutional authority means claims are taken at face value in a way no commercial site can replicate. Primarily serves an industry and policy audience but consumer guidance pages function as benchmark references that other sites cite.", "notable_tools": ["Structured glossary pages that define terms with precision — not just plain English but accurate plain English that a policy document would use", "Data and statistics hub where journalists, researchers, and consumers can find cited primary figures — an authority resource that pulls inbound links naturally", "Topic-based navigation that routes consumers from a general worry (home insurance, flooding) to the specific relevant guidance — reduces friction for non-expert visitors"], "trust_signals": ["Institutional identity — the ABI is a statutory-adjacent body whose name carries independent verification of credibility", "Payout statistics cited with methodology — £7.84 billion paid out is a specific, verifiable figure, not a vague claim", "Press release format with dates — signals that claims are time-stamped and accountable", "Explicit separation of 'policy and guidance' (factual/regulatory) from 'news' (current events and advocacy) — structural honesty about what type of content the reader is viewing", "No commercial calls to action on consumer guidance pages — the absence of 'get a quote' on an information page is a powerful trust differentiator"], "success_factors": ["Institutional authority means readers arrive with a prior assumption that the information is correct — the ABI's position as trade body does the trust-building before a word is read", "Consumer guidance pages define the canonical version of key terms and concepts — when the ABI defines 'reinstatement value', that definition is what FOS and courts will recognise", "Press releases and data publications (payout statistics, claims volumes) function as citable primary sources — giving other content producers a reason to link to and reference the site", "Policy and guidance section separates regulatory fact from editorial opinion — a structural choice that prevents the site from overreaching its remit", "Seasonal and topical news hooks (adverse weather, cold weather advice) demonstrate that insurance information is not static — it responds to real events in readers' lives", "Clean separation between industry-facing and consumer-facing content stops the site from feeling like it is writing for insurers when a consumer arrives seeking help"]}, {"url": "https://www.nfumutual.co.uk", "positioning": "The dominant UK agricultural insurance incumbent — positioned as a mutual insurer that exists for farmers rather than shareholders, which creates emotional alignment with an audience that is structurally suspicious of financial services companies. The farming-community identity is baked into the brand name, not bolted on.", "notable_tools": ["Local agent finder — the tool most important to the actual purchase decision, because farm insurance complexity requires human broker involvement for most customers", "Online account management for existing policyholders — reduces friction at renewal and claims stage, which are the two highest-stakes moments in the customer relationship", "News and stories editorial section that publishes seasonal farming content — functions as an organic search and loyalty driver independent of the product pages"], "trust_signals": ["Mutual ownership — structurally aligned with policyholders rather than shareholders, and communicated as such", "Sector-specific identity — the NFU name signals exclusive focus on farming and rural communities, not a general insurer with an agricultural product as an afterthought", "Charitable trust — tangible, ongoing community investment that cannot be faked short-term", "Local agent network — real people with local knowledge as a trust mechanism for a complex, high-value product", "Longevity — an established insurer with a multi-decade track record is implicitly more credible than a new entrant for a product that requires paying out on catastrophic claims"], "success_factors": ["Mutual ownership structure is a genuine differentiation that creates authentic community alignment — farmers understand that a mutual's interests are structurally closer to their own than a shareholder-owned insurer", "Agricultural content organisation reflects how farmers actually think about their year — by season, by livestock type, by farm enterprise — rather than by insurance product category", "Breadth of cover types (farm, rural business, equine, home, events) reflects the actual diversity of a modern farm business — a single-policy approach to farm diversification activities signals that NFU Mutual understands what its customers actually do", "News and stories section publishes content on non-insurance farm topics — risk management, rural events, charitable activity — making the site a genuine farming community resource rather than a pure product catalogue", "Local agent network is prominently signalled — for a complex product like farm insurance, the ability to speak to a person who knows the local area and farm type is a major purchase decision factor", "Business insurance framing acknowledges that modern farms are businesses — positioning farm insurance as business-grade cover rather than agricultural commodity cover raises the perceived quality of the product", "Charitable trust activities signal long-term community investment — differentiates from transactional insurers and supports the mutual positioning authentically"]}], "differentiation_opportunity": "None of the three exemplars serves the reader who is mid-crisis rather than mid-research. MSE covers complaint rights broadly, ABI covers industry statistics, and NFU Mutual covers its own product range — but none provides a deep, independent, scenario-led resource specifically for UK farmers who are currently navigating a claim dispute, a coverage gap discovered at claim time, or an insurer refusal. The 'what to do when your claim is refused' guide and the 'questions to ask your loss adjuster' content represent a gap that no incumbent fills adequately for the agricultural audience. A farmer who has just had a grain store fire claim disputed does not need a product guide — they need to know their rights under ICOBS, how to escalate to the FOS, what evidence to gather, and what the insurer is legally required to do. Farmerinsurance.uk can own this moment — the claims crisis moment — in a way that neither an insurer site (which has a conflict of interest) nor a general consumer site (which lacks farming specificity) can match. Combined with the seasonal risk content, this creates a resource that a farmer bookmarks before a problem occurs and returns to urgently when one does — the highest-value content relationship an information site can build."}$j674v$::jsonb, 'owner_review', 'copy_quality_two_stage',
        'Supersedes a7ce9ee2-c485-4f6f-89c9-cab311e13fdb per the owner cull ruling (decision 4, 2026-08-31): the seven deleted tools removed from prescription prose; exemplar analysis kept; predecessor retained (superseded, not deleted). Surgery + class battery: copy_quality_two_stage lane, 674.',
        true, 'copy_quality_two_stage');

DO $verify$
DECLARE n int; bad text;
BEGIN
  -- exactly one current row per aspect, and it is ours
  SELECT count(*) INTO n FROM site_specs
   WHERE site_id='99cae989-2413-430d-b026-59dfeeb638c0' AND aspect IN ('briefing','strategy','vertical_landscape')
     AND is_current AND created_by='copy_quality_two_stage';
  IF n <> 3 THEN RAISE EXCEPTION '674 VERIFY: % current successor rows, want 3', n; END IF;
  -- full class battery on the successors: no deleted-tool prescription survives
  SELECT string_agg(aspect, ', ') INTO bad FROM site_specs
   WHERE site_id='99cae989-2413-430d-b026-59dfeeb638c0' AND aspect IN ('briefing','strategy','vertical_landscape')
     AND is_current AND data::text ~* '(rebuild cost estimator|needs[ -]checker|livestock value estimator|seasonal risk calendar|jargon decoder|complaint eligibility checker|declared value calculator|illustrative tool|tool suite)';
  IF bad IS NOT NULL THEN RAISE EXCEPTION '674 VERIFY: class battery fired on successor aspect(s): % — nothing committed', bad; END IF;
  -- positive control: the battery must FIRE on all three kept predecessors
  SELECT count(*) INTO n FROM site_specs
   WHERE id IN ('38666a42-e9b5-4a81-aa2f-ab6aa2da9c44','43b01298-b25c-4e6c-abfb-0506bd0e3d78','a7ce9ee2-c485-4f6f-89c9-cab311e13fdb')
     AND data::text ~* '(rebuild cost estimator|needs[ -]checker|livestock value estimator|seasonal risk calendar|jargon decoder|complaint eligibility checker|declared value calculator|illustrative tool|tool suite)';
  IF n <> 3 THEN RAISE EXCEPTION '674 VERIFY CONTROL: battery fires on only % of 3 predecessors — the battery cannot see what it checks for; do not trust the clean result', n; END IF;
  RAISE NOTICE '674 verify: 3 successors current and battery-clean; control fired on all 3 predecessors.';
END $verify$;

